// GENERATED by ./gradlew :core:generateWebBoat - do not edit.
//
// The hull, deck, coachroof, appendages, standing rig and deck gear, as
// generated by HullLoft in `core`. Baked rather than transliterated: the
// geometry is static, so a second implementation would be six hundred lines
// of duplication kept in step by a checksum, with nothing gained. The sails
// are still built in the browser, because they move.
//
// 2685 vertices, 3200 triangles.

const decode = (text, Type) => {
  const binary = atob(text);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Type(bytes.buffer);
};

export const HULL_MESH = {
  positions: decode('', Float32Array),
  normals: decode('', Float32Array),
  materials: decode('', Float32Array),
  uvs: decode('', Float32Array),
  indices: decode('', Uint16Array),
};
